using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using Codice.Characters;using Codice.Mechanics;using Codice.Presentation;using Codice.UI;
public static class VerifyDodgeCancel {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 public static async Task<string> Run(){foreach(var role in new[]{PlayerClass.Warrior,PlayerClass.Archer,PlayerClass.Mage,PlayerClass.Shinobi,PlayerClass.Berserker}){var old=RunDirector.Instance?RunDirector.Instance.Player:null;typeof(RunNavigation).GetField("<SelectedClass>k__BackingField",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,role);SceneManager.LoadScene("SalaPruebas");for(int i=0;i<150&&(!RunDirector.Instance||!RunDirector.Instance.Player||RunDirector.Instance.Player==old);i++)await Task.Delay(100);await Task.Delay(500);var p=RunDirector.Instance.Player;p.enabled=false;p.SetNarrativeControlsBlocked(false);var combat=p.GetComponent<PlayerCombat>();combat.enabled=false;Check(combat.TryAttack(),"Cannot start attack "+role);Check(p.TryDash(Vector3.forward),"Windup cancel rejected "+role);Check(p.IsDashing&&!combat.IsSwinging,"Swing survived roll "+role);Check(!(p.GetComponent<StaffSpells>()?.Casting??false),"Cast survived "+role);Check(!p.TryDash(Vector3.forward),"Cooldown bypass "+role);await Task.Delay(650);Check(!combat.IsSwinging,"Deferred attack survived "+role);Debug.Log("[DodgeCancelTest] PASS "+role+" early cancel, roll state, cooldown, delayed action invalidation");}return "PASS 5 classes: windup cancellation and cooldown";}
}
